// Pathfinder 2e Remaster rules data, generated by `scripts/pf2e-data.ts` from Archives of
// Nethys (ORC content from the setting-neutral rulebooks only, nothing from Golarion setting
// books or named for its deities and places; see `data/pf2e/NOTICE.md`). Every record keeps
// its AoN id and the book and printed page it comes from. Deities are Paizo Reserved Material,
// included under Paizo's Community Use Policy (see the notice); book art is never included.
import type { Pf2eAttr, Pf2eRank } from '~/types/sheets'

export interface Pf2eSource {
  book: string
  /** Printed page; absent for web-only articles. */
  page?: number
}

export type Pf2eRarity = 'common' | 'uncommon' | 'rare' | 'unique'

/**
 * 1–3 actions, a reaction, a free action, a range or choice of those ("1 to 3", "free or 1",
 * "2 to 2 rounds"), or a time for activities ("1 minute").
 */
export type Pf2eActionCost = 1 | 2 | 3 | 'reaction' | 'free' | string

export interface Pf2eRecord {
  /** AoN document id, e.g. `feat-4775`: unique and stable. */
  id: string
  name: string
  source: Pf2eSource
  rarity: Pf2eRarity
  traits: string[]
  /** Rules text as markdown, without the title, traits, source and stat lines. */
  text: string
  /** Names of the legacy entries this one replaces. */
  replaces?: string[]
  /**
   * What AoN's entry leaves out that the book prints (a druidic order's skill, feat and order
   * spell; an awakened animal's Hit Points), for the builder to say instead of guessing.
   */
  gap?: string
}

export interface Pf2eClassFeature {
  id: string
  name: string
  level: number
  text: string
}

export interface Pf2eSubclassOption extends Pf2eRecord {
  /** The book's name for the choice, e.g. "Bard Muse", "Druidic Order". */
  kind: string
  /** For options with levels (runesmith runes, commander tactics). */
  level?: number
  /** Skills the option makes you trained in (a patron's, a rogue's racket…). */
  skills: string[]
  /** The spell tradition it sets (a sorcerer's bloodline, a witch's patron, an eidolon). */
  traditions: string[]
  /** Witch lessons: "Basic", "Greater" or "Major". */
  lessonType?: string
  /** Commander tactics: "Mobility", "Offensive"… */
  tacticType?: string
  /** Exemplar ikons and runesmith runes: what it's imbued into or drawn on. */
  usage?: string
  frequency?: string
  requirements?: string
  /** Summoner eidolons: their tradition and home plane. */
  tradition?: string
  homePlane?: string
}

export interface Pf2eClassDef extends Pf2eRecord {
  slug: string
  /** Key attribute; two when the class lets you choose. */
  keyAttributes: Pf2eAttr[]
  /** Hit Points per level, before CON. */
  hp: number
  perception: Pf2eRank
  saves: { fortitude: Pf2eRank; reflex: Pf2eRank; will: Pf2eRank }
  /** Initial proficiency lines as printed ("Trained in martial weapons"). */
  skills: string[]
  attacks: string[]
  defenses: string[]
  /** Spell tradition(s), for spellcasting classes. */
  traditions: string[]
  /** Class advancement table: what each level grants, by the book's names. */
  advancement: { level: number; features: string[] }[]
  /** Spells per day for slot casters: cantrips, then slots for ranks 1–10. */
  spellSlots?: { level: number; cantrips: number; slots: number[] }[]
  features: Pf2eClassFeature[]
  subclasses: Pf2eSubclassOption[]
}

export interface Pf2eAncestryDef extends Pf2eRecord {
  slug: string
  hp: number
  size: string[]
  speed: number
  /** Attribute boosts: attribute names, or "Free" once per free boost (Human: two "Free"). */
  boosts: string[]
  flaws: string[]
  languages: string[]
  vision?: string
}

/** Speeds by movement type, in feet. */
export type Pf2eSpeeds = Partial<Record<'land' | 'climb' | 'swim' | 'fly' | 'burrow', number>>

export interface Pf2eHeritageDef extends Pf2eRecord {
  /**
   * The ancestry's slug (`Pf2eAncestryDef.slug`; feats name ancestries by name instead).
   * Absent for versatile heritages.
   */
  ancestry?: string
  versatile: boolean
  /** Speeds the heritage text grants ("a land Speed of 20 feet, a climb Speed of 20 feet"). */
  speeds?: Pf2eSpeeds
}

export interface Pf2eBackgroundDef extends Pf2eRecord {
  /** Attribute names it may boost (one of them, plus a free boost). */
  boosts: string[]
  /**
   * Skills it trains outright, plus AoN's wording for a Lore the player names ("Lore related
   * to the terrain you worked in").
   */
  skills: string[]
  /**
   * Skills to pick from: "your choice of the Arcana, Nature, Occultism, or Religion skill",
   * "the Legal Lore skill or Warfare Lore skill". No options means any skill.
   */
  skillChoices?: { options: string[]; count: number }[]
  /** Trained in your deity's skill (Raised by Belief): the builder fills it in from the deity. */
  deitySkill?: boolean
  feats: string[]
}

export interface Pf2eFeatDef extends Pf2eRecord {
  level: number
  actions?: Pf2eActionCost
  prerequisites?: string
  trigger?: string
  requirements?: string
  frequency?: string
  cost?: string
  /** Who may take an uncommon feat without other access ("You are from Ustalav."). */
  access?: string
  /** Exemplar feats: the ikon it's imbued into. */
  usage?: string
  duration?: string
  /** Class names whose feat list includes it (by trait). */
  classes: string[]
  /** Ancestry or versatile heritage names whose feat list includes it. */
  ancestries: string[]
  /** Archetypes whose feat list includes it (Player Core p. 215). */
  archetypes: string[]
  /**
   * The level an archetype lists it at when that differs from `level` (an Additional Feat,
   * Player Core p. 215: Advanced Warden is a 6th-level Beastmaster feat).
   */
  archetypeLevels?: Record<string, number>
  general: boolean
  skill: boolean
}

/**
 * An archetype (Player Core pp. 215–216): its introduction, AoN's categories (Multiclass for
 * the class archetypes, Combat Style, Profession…) and its dedication feat. The feats are in
 * `feats`, by their `archetypes`.
 */
export interface Pf2eArchetypeDef extends Pf2eRecord {
  /** The level of its dedication feat. */
  level: number
  categories: string[]
  prerequisites?: string
  /** The dedication feat's AoN id. */
  dedication?: string
}

/** The class options that list a spell, by name ("Lesson of Shadow", a deity's domain…). */
export interface Pf2eSpellLinks {
  domains?: string[]
  bloodlines?: string[]
  mysteries?: string[]
  lessons?: string[]
  patronThemes?: string[]
}

/** `step` for "Heightened (+N)"; `ranks` for each "Heightened (Nth)" entry. A spell may have both. */
export interface Pf2eHeightening {
  step?: number
  ranks: number[]
}

export interface Pf2eSpellDef extends Pf2eRecord, Pf2eSpellLinks {
  rank: number
  kind: 'spell' | 'cantrip' | 'focus'
  traditions: string[]
  actions?: Pf2eActionCost
  range?: string
  area?: string
  targets?: string
  duration?: string
  /** Saving throw or defense, e.g. "basic Reflex". */
  defense?: string
  trigger?: string
  requirements?: string
  /** A material or other cost to cast (rituals and a few spells). */
  cost?: string
  heightened?: Pf2eHeightening
  /** A psychic's amped heightening ("Amp Heightened (+2)"). */
  ampHeightened?: Pf2eHeightening
  /** Focus spells and class cantrips (compositions, hexes): the classes they belong to (a domain
   * spell is the cleric's). */
  classes: string[]
}

export interface Pf2eWeaponDef extends Pf2eRecord {
  level: number
  /** Price in copper pieces. */
  price: number
  bulk: number
  hands: string
  damage: string
  damageTypes: string[]
  category: string
  group: string
  type: 'Melee' | 'Ranged'
  range?: number
  /** Actions to reload, or the printed time when it isn't counted in actions ("1 minute"). */
  reload?: number | string
}

export interface Pf2eArmorDef extends Pf2eRecord {
  level: number
  price: number
  bulk: number
  category: string
  group?: string
  ac: number
  dexCap?: number
  checkPenalty: number
  speedPenalty: number
  strength?: number
}

export interface Pf2eShieldDef extends Pf2eRecord {
  level: number
  price: number
  bulk: number
  ac: number
  hardness: number
  hp: number
  speedPenalty: number
}

/**
 * What an item is: adventuring gear, a consumable (potion, elixir, scroll, talisman, magical
 * or alchemical ammunition, oil, bomb), a held or worn magic item, a weapon or armor rune, a
 * staff or a wand (GM Core chapter 11).
 */
export type Pf2eItemKind =
  | 'gear'
  | 'potion'
  | 'elixir'
  | 'scroll'
  | 'talisman'
  | 'ammunition'
  | 'oil'
  | 'bomb'
  | 'held'
  | 'worn'
  | 'rune'
  | 'staff'
  | 'wand'

/**
 * An item's activation (GM Core p. 220): its actions, or what it takes when that isn't only
 * actions ("Cast a Spell", "Strike"), traits, frequency, trigger, requirements and effect.
 * A consumable's effect is its rules text.
 */
export interface Pf2eActivation {
  /** The activation's own name ("Activate—Dim the Lights"). */
  name?: string
  actions?: Pf2eActionCost
  /** "Cast a Spell", "Strike", "Interact" when the line names one. */
  as?: string
  traits: string[]
  frequency?: string
  trigger?: string
  requirements?: string
  cost?: string
  effect?: string
}

/**
 * A bonus an item gives to a statistic the sheet rolls (Player Core p. 400). One that holds
 * only sometimes ("to High Jump and Long Jump", "against poisons") keeps its sentence in
 * `when` and is shown, not applied.
 */
export interface Pf2eItemBonus {
  value: number
  type: 'item' | 'status' | 'circumstance'
  selector: Pf2eSelector
  skills?: string[]
  when?: string
}

export interface Pf2eItemDamage {
  dice: string
  /** Lowercase damage type ("fire"). */
  type: string
}

/** A rune's numbers (GM Core pp. 224–237). */
export interface Pf2eRuneNumbers {
  /** A fundamental rune (potency, striking, resilient) or a property rune. */
  slot: 'potency' | 'striking' | 'resilient' | 'property'
  onto: 'weapon' | 'armor'
  /** Potency +1–3; striking 1–3 (striking, greater, major); resilient +1–3. */
  value?: number
  /** A property rune's damage on a hit (flaming: 1d6 fire). */
  damage?: Pf2eItemDamage
  /** What it does on a critical hit, as printed. */
  crit?: string
  /** Its Usage line: "etched onto a melee weapon", "etched onto light armor". */
  usage: string
}

/** The numbers the sheet uses from an item, read from its text by the generator. */
export interface Pf2eItemNumbers {
  /** Hit Points it restores (Healing Potion (Minor): 1d8, GM Core p. 259). */
  healing?: string
  /** Bonuses it gives: a consumable's while its effect lasts, a worn or held item's always. */
  bonuses?: Pf2eItemBonus[]
  /** How long a consumable's effect lasts ("1 minute", "10 minutes"). */
  duration?: string
  /** A bomb (GM Core p. 244): damage, persistent and splash damage, item bonus to its attack. */
  bomb?: {
    damage: Pf2eItemDamage
    persistent?: Pf2eItemDamage
    splash?: number
    attack?: number
  }
  rune?: Pf2eRuneNumbers
  /** A staff's spells by rank (cantrips at 0), its lower types' included (GM Core p. 278). */
  spells?: { rank: number; names: string[] }[]
  /** The spell rank a scroll or wand holds (GM Core pp. 262, 282). */
  spellRank?: number
}

/**
 * An item from GM Core and the other open books: one record per grade for items printed with
 * several ("Healing Potion (Lesser)"), its text the item's own followed by the grade's.
 */
export interface Pf2eItemDef extends Pf2eRecord, Pf2eItemNumbers {
  kind: Pf2eItemKind
  /** AoN's id of the entry the grades share. */
  parent?: string
  level: number
  /** Price in copper pieces. */
  price: number
  /** 0.1 is light (L), 0 negligible. */
  bulk: number
  usage?: string
  activations: Pf2eActivation[]
}

export interface Pf2eConditionDef extends Pf2eRecord {
  /** Has a value, like frightened 2. */
  valued: boolean
}

export interface Pf2eActionDef extends Pf2eRecord {
  actions?: Pf2eActionCost
  trigger?: string
  requirements?: string
  frequency?: string
  cost?: string
}

export type Pf2eTraitDef = Pf2eRecord

/** A deity (Reserved Material, under Paizo's Community Use Policy). */
export interface Pf2eDeityDef extends Pf2eRecord {
  epithet?: string
  category: string
  edicts: string
  anathema: string
  areasOfConcern: string[]
  /** The divine attribute options (a cleric picks one). */
  attributes: Pf2eAttr[]
  /** Heal, harm or both. */
  divineFont: string[]
  /** e.g. "can choose holy or unholy"; absent when the deity grants none. */
  sanctification?: string
  /** The divine skill. */
  skill: string[]
  favoredWeapons: string[]
  domains: string[]
  alternateDomains: string[]
  /** Spells a cleric of this deity adds to their list, by name. */
  clericSpells: string[]
}

/** What a modifier applies to. `checks` is every check and DC; `saves` every saving throw. */
export type Pf2eSelector =
  | 'ac'
  | 'attack'
  | 'damage'
  | 'perception'
  | 'fortitude'
  | 'reflex'
  | 'will'
  | 'saves'
  | 'skills'
  | 'checks'
  | 'speed'
  | 'initiative'

/**
 * One structured piece of what an ability does, read by `utils/pf2eEffects.ts`. Hand-written
 * per ability in `data/pf2e/effects.ts` from its rules text; anything the kinds can't say
 * stays in `note` for the player.
 */
export type Pf2eEffect =
  /**
   * A bonus or penalty. `melee` limits it to melee Strikes, `weapons` to agile or finesse
   * ones, `skills` to the named skills; `agileHalf` halves it for agile attacks; `byLevel`
   * replaces `value` from a level on (the last entry at or below the hero's level).
   */
  | {
      kind: 'modifier'
      selector: Pf2eSelector[]
      value: number
      type: 'status' | 'circumstance' | 'item' | 'untyped'
      melee?: boolean
      agileHalf?: boolean
      /** Agile or finesse Strikes (Precise Strike), or unarmed ones (an animal instinct's). */
      weapons?: 'agileFinesse' | 'unarmed'
      skills?: string[]
      byLevel?: [level: number, value: number][]
      /** Effects whose bonus of the same type this one adds to instead of the higher counting. */
      cumulativeWith?: string[]
      /** Only for these actions' checks, rolled from the Actions panel (Make an Impression). */
      actions?: string[]
      /** From this level on (a doctrine's or specialization's later benefit). */
      level?: number
    }
  /** A different multiple attack penalty (the Flurry edge against hunted prey). */
  | { kind: 'map'; second: number; third: number; agileSecond: number; agileThird: number }
  /** Damage with finesse melee Strikes uses this attribute when it's higher (Thief). */
  | { kind: 'damageAttribute'; attr: Pf2eAttr }
  /** Damage by the Strike's proficiency rank (weapon specialization). */
  | { kind: 'specialization'; damage: Partial<Record<Pf2eRank, number>> }
  /** A condition the effect gives (Enlarge: clumsy 1; Haste: quickened). */
  | { kind: 'condition'; name: string; value?: number }
  /** A Dexterity cap on AC (Mountain Stance: +0). */
  | { kind: 'dexCap'; value: number }
  /** Extra damage dice on Strikes while a condition holds (sneak attack on an off-guard foe). */
  | {
      kind: 'damageDice'
      /** Dice by level: the last entry at or below the hero's level applies. */
      dice: [level: number, dice: string][]
      /** `always`: while the effect is on (Qi Form's 1d6, Weapon Surge's spirit dice). */
      when: 'offGuard' | 'huntedPrey' | 'stratagem' | 'always'
      /** Which Strikes: agile, finesse or ranged (sneak attack), or unarmed (Inner Upheaval). */
      weapons?: 'agileFinesseRanged' | 'unarmed'
      label: string
    }
  /** Temporary Hit Points when turned on: level + CON (Rage), level, half level, a number. */
  | { kind: 'tempHp'; formula: Pf2eAmount }
  /** The dying value at which the hero dies (Diehard: 5). */
  | { kind: 'deathAt'; value: number }
  /** Change to recovery check DCs (Toughness: −1). */
  | { kind: 'recoveryDc'; value: number }
  /** A degree of success turned into another on a save (Juggernaut: success → critical success). */
  | {
      kind: 'degree'
      save: 'Fortitude' | 'Reflex' | 'Will' | 'all'
      from: Pf2eDegreeName
      to: Pf2eDegreeName
      /** Only against these effects ("a fear effect"): shown on the roll, not applied. */
      against?: string
      level?: number
    }
  /** A proficiency rank the ability raises the statistic to (Juggernaut: Fortitude master). */
  | {
      kind: 'proficiency'
      stat: 'Fortitude' | 'Reflex' | 'Will' | 'Perception' | 'Class DC' | 'AC' | 'attack' | 'spell'
      rank: Pf2eRank
      level?: number
    }
  /** Resistance the hero has, by an amount or a formula, plus `add` (Raging Resistance: 3 + CON). */
  | {
      kind: 'resistance'
      type: string
      amount: Pf2eAmount
      add?: number
      min?: number
      level?: number
    }
  /** The fist's damage die (Powerful Fist: d6). */
  | { kind: 'fistDie'; die: number }

/** An amount by the hero's level or Constitution, or a number. */
export type Pf2eAmount =
  | number
  | 'level'
  | 'halfLevel'
  | 'doubleLevel'
  | 'tripleLevel'
  | 'con'
  | 'levelPlusCon'

export type Pf2eDegreeName = 'critical success' | 'success' | 'failure' | 'critical failure'

/** When a toggle turned on by a use ends by itself (Shield: at the start of your next turn). */
export type Pf2eEnds =
  | 'startOfTurn'
  | 'endOfTurn'
  | 'endOfNextTurn'
  | 'trigger'
  | 'minute'
  | 'encounter'

export interface Pf2eEffectDef {
  /** The feat, class feature, action or spell it belongs to, by name. */
  name: string
  source: Pf2eSource
  /**
   * `permanent`: on whenever the hero has the ability. `toggle`: the hero turns it on.
   * `given`: an ally's effect on the hero (Bless), chosen from a list.
   */
  mode: 'permanent' | 'toggle' | 'given'
  /**
   * The ability the hero must have when `name` isn't one (a barbarian instinct's Rage damage,
   * a bloodline's blood magic), and its kind ("Instinct", "Bloodline") when names repeat.
   */
  has?: { name: string; type?: string }
  effects: Pf2eEffect[]
  /** Values for a `given` effect that scales (Heroism +1/+2/+3); modifiers use the chosen one. */
  values?: number[]
  /** Only while this other effect is on (the ranger's edges need Hunt Prey). */
  requires?: string
  /** A toggle that ends when the hero falls unconscious (Rage). */
  endsWhenUnconscious?: boolean
  /** Rules the effect can't apply itself, shown while it's on. */
  note?: string
  /** A toggle that ends by itself, by the turn steps. */
  ends?: Pf2eEnds
  /** Read from the ability's text by utils/pf2eAbilityRules.ts rather than written here. */
  derived?: boolean
}
